// 1) Coletores: aceita tanto entrada como array de itens do nódulo anterior
//    quanto um único item cujo JSON seja um array.
let docs = $input.all().map(i => i.json);
if (Array.isArray(docs[0])) docs = docs[0]; // desembrulha se veio como array dentro de um único item

// 2) Pequena limpeza opcional do texto
const clean = (s='') =>
  s.replace(/\u00ad/g, '')           // remove soft-hyphen
   .replace(/[ \t]+\n/g, '\n')       // tira espaços antes de quebra de linha
   .replace(/\n{3,}/g, '\n\n');      // colapsa múltiplas quebras

// 3) Chunking simples (ajuste size/overlap conforme seu embedder)
function chunkText(text, size = 1000, overlap = 150) {
  const out = [];
  let i = 0;
  while (i < text.length) {
    const end = Math.min(i + size, text.length);
    out.push(text.slice(i, end));
    if (end === text.length) break;
    i = Math.max(0, end - overlap);
  }
  return out;
}

// 4) Mapeia cada PDF -> vários itens (um por chunk) no formato que o SVS espera
const out = [];
for (const d of docs) {
  const fullText = clean(d.text || '');
  const chunks = chunkText(fullText, 1000, 150);

  // tenta achar autor/título nas chaves disponíveis
  const author = d.info?.Author || (Array.isArray(d.metadata?.['dc:creator']) ? d.metadata['dc:creator'][0] : undefined);
  const created = d.info?.CreationDate || d.metadata?.['xmp:createdate'];

  chunks.forEach((c, idx) => {
    out.push({
      json: {
        text: c,
        metadata: {
          // se você estiver carregando o link_pdf desde passos anteriores, faça merge antes e preencha aqui:
          // source: $json.link_pdf,
          pages: d.numpages,
          pdf_version: d.info?.PDFFormatVersion,
          author,
          created,
          extractor_version: d.version,
          chunk: idx + 1
        }
      }
    });
  });
}

return out;

// Pega o primeiro item retornado pelo GitHub Node
const raw = Buffer.from($input.first().json.content, 'base64').toString('utf-8');

// Converte para objeto JSON
const data = JSON.parse(raw);

// Retorna cada artigo como um item separado
//return data.artigos.map(artigo => ({ json: artigo }));
return data.artigos.map((a, i) => ({
  json: {
    id: i + 1,
    titulo: a.titulo,
    autor: a.autor,
    ano: a.ano,
    link_pdf: a.link_pdf
  }
}));
